 73	 */
 74	export function distributeToColumns(tasks: TaskSummary[]): BoardColumn[] {
 75		const backlog: TaskSummary[] = [];
 76		const ready: TaskSummary[] = [];
 77		const inProgress: TaskSummary[] = [];
 78		const review: TaskSummary[] = [];
 79		const done: TaskSummary[] = [];
 80	
 81		for (const task of tasks) {
 82			switch (task.status) {
 83				case 'pending': {
 84					const auto = task.automation;
 85					if (auto === 'eligible') {
 86						ready.push(task);
 87					} else {
 88						// manual_only, unassessed, or undefined → backlog
 89						backlog.push(task);
 90					}
 91					break;
 92				}
 93				case 'in_progress':
 94				case 'needs_work':
 95					inProgress.push(task);
 96					break;
 97				case 'pending_review':
 98					review.push(task);
 99					break;
100				case 'completed':
101					done.push(task);
102					break;
103				case 'blocked':
104					// Show blocked tasks in their original column context (in_progress column)
105					inProgress.push(task);
106					break;
107				case 'cancelled':
108					// Show cancelled tasks in done column with indicator
109					done.push(task);
110					break;
111			}
112		}
