  1	/**
  2	 * API Response Types
  3	 *
  4	 * Shared types for REST API responses between daemon and web-ui.
  5	 * These types define the contract for HTTP endpoints.
  6	 */
  7	
  8	/**
  9	 * Common paginated response wrapper
 10	 * AC: @api-contract ac-4
 11	 */
 12	export interface PaginatedResponse<T> {
 13	  items: T[];
 14	  total: number;
 15	  offset: number;
 16	  limit: number;
 17	}
 18	
 19	/**
 20	 * Standard error response
 21	 * AC: @api-contract ac-22, ac-23, ac-24
 22	 */
 23	export interface ErrorResponse {
 24	  error: string;
 25	  message?: string;
 26	  suggestion?: string;
 27	  details?: Array<{ field: string; message: string }>;
 28	  current?: string;
 29	  valid_transitions?: string[];
 30	}
 31	
 32	/**
 33	 * Task summary for list endpoints
 34	 * AC: @api-contract ac-2
 35	 */
 36	export interface TaskSummary {
 37	  _ulid: string;
 38	  slugs: string[];
 39	  title: string;
 40	  type: string;
 41	  status: string;
 42	  priority: number;
 43	  spec_ref?: string;
 44	  tags: string[];
 45	  depends_on: string[];
 46	  created_at: string;
 47	  started_at?: string;
 48	  notes_count: number;
 49	  todos_count?: number;
 50	  automation?: string;
 51	}
 52	
 53	/**
 54	 * Full task with notes and todos
 55	 * AC: @api-contract ac-5
 56	 */
 57	export interface TaskDetail extends TaskSummary {
 58	  description?: string;
 59	  derivation?: string;
 60	  blocked_by: string[];
 61	  depends_on: string[];
 62	  context: string[];
 63	  vcs_refs: string[];
 64	  plan_ref?: string;
 65	  session_ref?: string;
 66	  notes: Note[];
 67	  todos?: Todo[];
 68	}
 69	
 70	/**
 71	 * Task note
 72	 */
 73	export interface Note {
 74	  _ulid: string;
 75	  created_at: string;
 76	  author: string;
 77	  content: string;
 78	  supersedes?: string;
 79	}
 80	
 81	/**
 82	 * Task todo
 83	 */
 84	export interface Todo {
 85	  _ulid: string;
 86	  content: string;
 87	  status: 'pending' | 'in_progress' | 'completed';
 88	  created_at: string;
 89	}
 90	
 91	/**
 92	 * Spec item summary for list endpoints
 93	 * AC: @api-contract ac-8
 94	 */
 95	export interface ItemSummary {
 96	  _ulid: string;
 97	  slugs: string[];
 98	  title: string;
 99	  type: string;
100	  status?: string;
101	  tags: string[];
102	  parent?: string;
103	  created_at: string;
104	}
105	
106	/**
107	 * Full spec item with ACs and traits
108	 * AC: @api-contract ac-10
109	 */
110	export interface ItemDetail extends ItemSummary {
111	  description?: string;
112	  acceptance_criteria: AcceptanceCriterion[];
113	  traits: string[];
114	  depends_on: string[];
115	  priority?: number;
116	}
