 16	import type { TaskSummary } from '../../shared/src/api';
 17	
 18	function makeTask(overrides: Partial<TaskSummary> = {}): TaskSummary {
 19		return {
 20			_ulid: '01ABC' + Math.random().toString(36).slice(2, 10).toUpperCase(),
 21			slugs: ['test-task'],
 22			title: 'Test Task',
 23			type: 'task',
 24			status: 'pending',
 25			priority: 3,
 26			tags: [],
 27			depends_on: [],
 28			created_at: new Date().toISOString(),
 29			notes_count: 0,
 30			...overrides
 31		};
 32	}
 33	
 34	describe('distributeToColumns', () => {
 35		// AC: @ui-task-board ac-1
 36		it('distributes pending+unassessed tasks to Backlog column', () => {
 37			const tasks = [
 38				makeTask({ status: 'pending', automation: undefined }),
 39				makeTask({ status: 'pending', automation: 'manual_only' })
 40			];
 41			const columns = distributeToColumns(tasks);
 42			const backlog = columns.find((c) => c.id === 'backlog')!;
 43			expect(backlog.tasks).toHaveLength(2);
 44		});
 45	
 46		// AC: @ui-task-board ac-1
 47		it('distributes pending+eligible tasks to Ready column', () => {
 48			const tasks = [makeTask({ status: 'pending', automation: 'eligible' })];
 49			const columns = distributeToColumns(tasks);
 50			const ready = columns.find((c) => c.id === 'ready')!;
 51			expect(ready.tasks).toHaveLength(1);
 52		});
 53	
 54		// AC: @ui-task-board ac-1
 55		it('distributes in_progress and needs_work to In Progress column', () => {
 56			const tasks = [
 57				makeTask({ status: 'in_progress' }),
 58				makeTask({ status: 'needs_work' })
 59			];
 60			const columns = distributeToColumns(tasks);
 61			const inProgress = columns.find((c) => c.id === 'in_progress')!;
 62			expect(inProgress.tasks).toHaveLength(2);
 63		});
 64	
 65		// AC: @ui-task-board ac-1
 66		it('distributes pending_review to Review column', () => {
 67			const tasks = [makeTask({ status: 'pending_review' })];
 68			const columns = distributeToColumns(tasks);
 69			const review = columns.find((c) => c.id === 'review')!;
 70			expect(review.tasks).toHaveLength(1);
