 73		// AC: @ui-task-board ac-1
 74		it('distributes completed to Done column (limited to 20)', () => {
 75			const tasks = Array.from({ length: 25 }, (_, i) =>
 76				makeTask({
 77					status: 'completed',
 78					created_at: new Date(Date.now() - i * 86400000).toISOString()
 79				})
 80			);
 81			const columns = distributeToColumns(tasks);
 82			const done = columns.find((c) => c.id === 'done')!;
