100			expect(done.tasks).toHaveLength(1);
101			expect(done.tasks[0].status).toBe('cancelled');
102		});
103	
104		// AC: @ui-task-board ac-1
105		it('sorts columns by priority (lower number = higher priority)', () => {
106			const tasks = [
107				makeTask({ status: 'pending', automation: 'eligible', priority: 5 }),
108				makeTask({ status: 'pending', automation: 'eligible', priority: 1 }),
109				makeTask({ status: 'pending', automation: 'eligible', priority: 3 })
110			];
111			const columns = distributeToColumns(tasks);
112			const ready = columns.find((c) => c.id === 'ready')!;
113			expect(ready.tasks[0].priority).toBe(1);
114			expect(ready.tasks[1].priority).toBe(3);
115			expect(ready.tasks[2].priority).toBe(5);
