121			expect(columns).toHaveLength(5);
122			expect(columns.map((c) => c.id)).toEqual([
123				'backlog',
124				'ready',
125				'in_progress',
126				'review',
127				'done'
128			]);
129		});
130	});
131	
132	describe('getStatusClasses', () => {
133		// AC: @ui-task-board ac-2
134		it('returns correct classes for all known statuses', () => {
135			const statuses = [
136				'pending',
137				'in_progress',
