170			expect(formatAge(threeHoursAgo)).toBe('3h');
171		});
172	
173		// AC: @ui-task-board ac-2
174		it('formats days', () => {
175			const fiveDaysAgo = new Date(Date.now() - 5 * 86400000).toISOString();
176			expect(formatAge(fiveDaysAgo)).toBe('5d');
177		});
178	});
179	
180	describe('formatElapsed', () => {
181		// AC: @ui-task-board ac-4
182		it('formats seconds', () => {
183			expect(formatElapsed(45000)).toBe('45s');
184		});
185	
186		// AC: @ui-task-board ac-4
187		it('formats minutes and seconds', () => {
188			expect(formatElapsed(125000)).toBe('2m 5s');
189		});
190	
191		// AC: @ui-task-board ac-4
192		it('formats hours and minutes', () => {
193			expect(formatElapsed(3725000)).toBe('1h 2m');
194		});
195	});
196	
197	describe('formatVcsRef', () => {
198		// AC: @ui-task-board ac-3
199		it('parses branch: prefix into label without URL', () => {
200			const result = formatVcsRef('branch:feat/my-feature');
201			expect(result.label).toBe('feat/my-feature');
202			expect(result.url).toBeNull();
203		});
204	
205		// AC: @ui-task-board ac-3
206		it('parses pr: prefix with number', () => {
207			const result = formatVcsRef('pr:42');
208			expect(result.label).toBe('PR #42');
209			expect(result.url).toBeNull();
210		});
211	
212		// AC: @ui-task-board ac-3
213		it('parses pr: prefix with URL', () => {
214			const result = formatVcsRef('pr:https://github.com/org/repo/pull/42');
215			expect(result.label).toBe('PR 42');
216			expect(result.url).toBe('https://github.com/org/repo/pull/42');
217		});
218	
219		// AC: @ui-task-board ac-3
220		it('parses direct GitHub PR URL', () => {
221			const result = formatVcsRef('https://github.com/org/repo/pull/99');
222			expect(result.label).toBe('PR #99');
223			expect(result.url).toBe('https://github.com/org/repo/pull/99');
224		});
225	
226		// AC: @ui-task-board ac-3
227		it('parses direct URL without PR pattern', () => {
228			const result = formatVcsRef('https://github.com/org/repo');
229			expect(result.label).toBe('repo');
230			expect(result.url).toBe('https://github.com/org/repo');
231		});
232	
233		// AC: @ui-task-board ac-3
234		it('returns plain text for unknown format', () => {
235			const result = formatVcsRef('some-ref');
236			expect(result.label).toBe('some-ref');
237			expect(result.url).toBeNull();
238		});
239	});
240	
241	describe('real-time update support', () => {
242		// AC: @ui-task-board ac-5
243		it('distributeToColumns is a pure function that can be re-called on data changes', () => {
244			// The board re-derives columns from $effect whenever tasks array changes.
245			// Verify that distributeToColumns produces correct output when called
246			// with updated data (simulating a WebSocket-triggered reload).
247			const initial = [makeTask({ status: 'pending', automation: 'eligible' })];
248			const columnsV1 = distributeToColumns(initial);
249			expect(columnsV1.find((c) => c.id === 'ready')!.tasks).toHaveLength(1);
250			expect(columnsV1.find((c) => c.id === 'in_progress')!.tasks).toHaveLength(0);
251	
252			// After a state change event, the tasks array is updated
253			const updated = [makeTask({ ...initial[0], status: 'in_progress' })];
254			const columnsV2 = distributeToColumns(updated);
255			expect(columnsV2.find((c) => c.id === 'ready')!.tasks).toHaveLength(0);
256			expect(columnsV2.find((c) => c.id === 'in_progress')!.tasks).toHaveLength(1);
257		});
258	
259		// AC: @ui-task-board ac-5
260		it('handles empty-to-populated transitions for real-time updates', () => {
261			// Board starts empty, then tasks arrive via WebSocket-triggered reload
262			const empty = distributeToColumns([]);
263			expect(empty.every((c) => c.tasks.length === 0)).toBe(true);
264	
265			const populated = distributeToColumns([
266				makeTask({ status: 'pending', automation: 'eligible' }),
