 1	/*
 2	 * Design System Animations
 3	 *
 4	 * All animations are gated behind @media (prefers-reduced-motion: reduce)
 5	 * to respect user accessibility preferences.
 6	 *
 7	 * Keyframes use the ds- prefix to avoid collisions.
 8	 */
 9	
10	/* ── Shimmer (skeleton loading) ── */
11	
12	@keyframes ds-shimmer {
13	  0% {
14	    background-position: 200% 0;
15	  }
16	  100% {
17	    background-position: -200% 0;
18	  }
19	}
20	
21	/* ── Breathing / Pulse (active agent indicator) ── */
22	
23	@keyframes ds-breathe {
24	  0%,
25	  100% {
26	    box-shadow:
27	      0 0 0 0 color-mix(in oklch, var(--design-accent) 10%, transparent),
28	      inset 0 0 20px color-mix(in oklch, var(--design-accent) 5%, transparent);
29	  }
30	  50% {
31	    box-shadow:
32	      0 0 20px 2px color-mix(in oklch, var(--design-accent) 20%, transparent),
33	      inset 0 0 30px color-mix(in oklch, var(--design-accent) 10%, transparent);
34	  }
35	}
36	
37	/* ── Utility classes ── */
38	
39	.ds-shimmer {
40	  background: linear-gradient(
41	    90deg,
42	    transparent 0%,
43	    color-mix(in oklch, var(--design-accent) 8%, transparent) 50%,
44	    transparent 100%
45	  );
46	  background-size: 200% 100%;
47	  animation: ds-shimmer 2s ease-in-out infinite;
48	}
49	
50	.ds-breathe {
51	  animation: ds-breathe 3s ease-in-out infinite;
52	}
53	
54	/* ── Reduced motion: disable all ds- animations ── */
55	
56	@media (prefers-reduced-motion: reduce) {
57	  .ds-shimmer {
58	    animation: none;
59	    background: color-mix(in oklch, var(--design-accent) 8%, transparent);
60	  }
61	
62	  .ds-breathe {
63	    animation: none;
64	  }
65	}

